  7→  let mockAxios: MockAdapter;
  8→  let getAccessToken: ReturnType<typeof vi.fn>;
  9→  let refreshAccessToken: ReturnType<typeof vi.fn>;
 10→  let onRefreshFailure: ReturnType<typeof vi.fn>;
 11→  const origCreate = axios.create.bind(axios);
 12→  let createSpy: ReturnType<typeof vi.spyOn>;
 13→
 14→  beforeEach(async () => {
 15→    getAccessToken = vi.fn().mockResolvedValue('initial-token');
 16→    refreshAccessToken = vi.fn().mockResolvedValue('refreshed-token');
 17→    onRefreshFailure = vi.fn();
 18→
 19→    createSpy = vi.spyOn(axios, 'create').mockImplementation((config) => {
 20→      const instance = origCreate(config);
 21→      mockAxios = new MockAdapter(instance);
 22→      return instance;
 23→    });
 24→
 25→    setApiClientConfig({
 26→      baseUrl: 'http://test-api',
 27→      getAccessToken,
 28→      refreshAccessToken,
 29→      onRefreshFailure,
 30→      withCredentials: true,
 31→    });
 32→
 33→    // Trigger instance creation so mockAxios is available for all tests.
 34→    // This warm-up request will fail because no routes are mocked yet — that's fine.
 35→    try {
 36→      mockAxios?.onGet('/__warmup').reply(200, {});
 37→    } catch {
 38→      // mockAxios not yet set — expected on first call
 39→    }
 40→    try {
 41→      await customInstance({ url: '/__warmup', method: 'GET' });
 42→    } catch {
 43→      // May fail — we just need the side effect of creating the instance
 44→    }
 45→    // Now mockAxios is set. Reset it for the actual test.
 46→    mockAxios.reset();
 47→  });
 48→
 49→  afterEach(() => {
 50→    createSpy.mockRestore();
 51→  });
 52→
 53→  it('retries with refreshed token on 401', async () => {
 54→    let callCount = 0;
 55→    mockAxios.onGet('/test').reply(() => {
 56→      callCount++;
 57→      if (callCount === 1) return [401, 'Unauthorized'];
 58→      return [200, { ok: true }];
 59→    });
 60→
 61→    const result = await customInstance({ url: '/test', method: 'GET' });
 62→
 63→    expect(result).toEqual({ ok: true });
 64→    expect(refreshAccessToken).toHaveBeenCalledOnce();
 65→    expect(callCount).toBe(2);
 66→  });
 67→
 68→  it('does not retry refresh endpoint to avoid infinite loop', async () => {
 69→    mockAxios.onPost('/auth/refresh').reply(401);
 70→
 71→    await expect(customInstance({ url: '/auth/refresh', method: 'POST' })).rejects.toThrow();
 72→
 73→    expect(refreshAccessToken).not.toHaveBeenCalled();
 74→  });
 75→
 76→  it('calls onRefreshFailure when refresh rejects', async () => {
 77→    refreshAccessToken.mockRejectedValue(new Error('refresh failed'));
 78→    mockAxios.onGet('/test').reply(401);
 79→
 80→    await expect(customInstance({ url: '/test', method: 'GET' })).rejects.toThrow();
 81→
 82→    expect(onRefreshFailure).toHaveBeenCalledOnce();
 83→  });
 84→
 85→  it('deduplicates concurrent refresh requests', async () => {
 86→    let refreshCallCount = 0;
 87→    refreshAccessToken.mockImplementation(
 88→      () =>
 89→        new Promise((resolve) => {
 90→          refreshCallCount++;
 91→          setTimeout(() => resolve('refreshed-token'), 50);
 92→        })
 93→    );
 94→
 95→    const callCounts: Record<string, number> = {};
 96→    mockAxios.onGet('/a').reply(() => {
 97→      callCounts['/a'] = (callCounts['/a'] ?? 0) + 1;
 98→      return callCounts['/a'] === 1 ? [401, 'Unauthorized'] : [200, { id: 'a' }];
 99→    });
100→    mockAxios.onGet('/b').reply(() => {
101→      callCounts['/b'] = (callCounts['/b'] ?? 0) + 1;
102→      return callCounts['/b'] === 1 ? [401, 'Unauthorized'] : [200, { id: 'b' }];
103→    });
104→
105→    const [resultA, resultB] = await Promise.all([
106→      customInstance({ url: '/a', method: 'GET' }),
107→      customInstance({ url: '/b', method: 'GET' }),
108→    ]);
109→
110→    expect(resultA).toEqual({ id: 'a' });
111→    expect(resultB).toEqual({ id: 'b' });
112→    expect(refreshCallCount).toBe(1);
113→  });
114→
115→  it('creates instance with withCredentials from config', () => {
116→    // Instance was already created in beforeEach
117→    expect(createSpy).toHaveBeenCalledWith(
118→      expect.objectContaining({
